@Test
public void testCreateEmptyExtensions() {
    assertEquals("Empty wanted extension array should create empty extension collection", FileTreeReader.createValidExtensions(new String[0]).size(), 0);
    assertEquals("Star * wanted extension array should create empty extension collection", FileTreeReader.createValidExtensions("*").size(), 0);
    assertEquals("dot Star .* wanted extension array should create empty extension collection", FileTreeReader.createValidExtensions(".*").size(), 0);
}

@Test
public void testCreateSimpleExtensions() {
    assertTrue("txt array should produce collection containing .txt", FileTreeReader.createValidExtensions("txt").contains(".txt"));
    assertTrue(".txt .bsv array should produce collection containing .txt", FileTreeReader.createValidExtensions(".txt").contains(".txt"));
}

