    assertTrue("txt.xmi array should produce collection containing .txt.xmi", FileTreeReader.createValidExtensions("txt.xmi").contains(".txt.xmi"));
    assertTrue(".txt.xmi array should produce collection containing .txt.xmi", FileTreeReader.createValidExtensions(".txt.xmi").contains(".txt.xmi"));
