@Test
public void testCreateTagDictionary() throws FileNotFoundException, IOException {
    InputStreamReader input = new InputStreamReader(this.getClass().getClassLoader().getResourceAsStream("data/unit-test-2lines-training-data.txt"));
    HashMap<String, Set<String>> tagDictionaryData = TagDictionaryCreator.createTagDictionary(new BufferedReader(input), true);
    Set<String> tags = tagDictionaryData.get("IL-2");
    assertEquals(3, tags.size());
    boolean nn = false;
    boolean cc = false;
    boolean in = false;
    for (String tag : tags) {
        if (tag.equals("NN"))
            nn = true;
        if (tag.equals("CC"))
            cc = true;
        if (tag.equals("IN"))
            in = true;
    }
    assertTrue(nn);
    assertTrue(cc);
    assertTrue(in);
    input = new InputStreamReader(this.getClass().getClassLoader().getResourceAsStream("data/unit-test-2lines-training-data.txt"));
    tagDictionaryData = TagDictionaryCreator.createTagDictionary(new BufferedReader(input), false);
    tags = tagDictionaryData.get("il-2");
    assertEquals(3, tags.size());
    nn = false;
    cc = false;
    in = false;
    for (String tag : tags) {
        if (tag.equals("NN"))
            nn = true;
        if (tag.equals("CC"))
            cc = true;
        if (tag.equals("IN"))
            in = true;
    }
    assertTrue(nn);
    assertTrue(cc);
    assertTrue(in);
    tags = tagDictionaryData.get("surface");
    assertEquals("NN", tags.iterator().next());
}

@Test
public void testMain() throws FileNotFoundException, IOException {
    String[] args = new String[] { "target/test-classes/data/unit-test-2lines-training-data.txt", "target/test-classes/data/output/unit-test-2lines-tag-dictionary.txt", "true" };
    TagDictionaryCreator.main(args);
    InputStreamReader reader = new InputStreamReader(this.getClass().getClassLoader().getResourceAsStream("data/output/unit-test-2lines-tag-dictionary.txt"));
    BufferedReader input = new BufferedReader(reader);
    String line;
    int lines = 0;
    while ((line = input.readLine()) != null) {
        lines++;
        if (line.startsWith("IL-2 "))
            assertEquals("IL-2 CC IN NN", line);
        if (line.startsWith("requires "))
            assertEquals("requires VBZ", line);
    }
    assertEquals(36, lines);
}

@Test
public void test() throws JDOMException {
    GeniaPosTrainingDataExtractor gptde = new GeniaPosTrainingDataExtractor("test/data/GENIAcorpus3.02.pos.test.xml");
    TaggedAbstract taggedAbstract = gptde.next();
    TaggedSentence taggedSentence;
    TaggedWord taggedWord;
    //test one full sentence from title
    taggedSentence = taggedAbstract.getTaggedSentences().get(0);
    taggedWord = taggedSentence.getTaggedWords().get(0);
    assertEquals("Pancreatic", taggedWord.getWord());
    assertEquals("JJ", taggedWord.getTag());
    taggedWord = taggedSentence.getTaggedWords().get(1);
    assertEquals("development", taggedWord.getWord());
    assertEquals("NN", taggedWord.getTag());
    taggedWord = taggedSentence.getTaggedWords().get(2);
    assertEquals("and", taggedWord.getWord());
    assertEquals("CC", taggedWord.getTag());
    taggedWord = taggedSentence.getTaggedWords().get(3);
    assertEquals("maturation", taggedWord.getWord());
    assertEquals("NN", taggedWord.getTag());
    taggedWord = taggedSentence.getTaggedWords().get(4);
    assertEquals("of", taggedWord.getWord());
    assertEquals("IN", taggedWord.getTag());
    taggedWord = taggedSentence.getTaggedWords().get(5);
    assertEquals("the", taggedWord.getWord());
    assertEquals("DT", taggedWord.getTag());
    taggedWord = taggedSentence.getTaggedWords().get(6);
    assertEquals("islet", taggedWord.getWord());
    assertEquals("NN", taggedWord.getTag());
    taggedWord = taggedSentence.getTaggedWords().get(7);
    assertEquals("B", taggedWord.getWord());
    assertEquals("NN", taggedWord.getTag());
    taggedWord = taggedSentence.getTaggedWords().get(8);
    assertEquals("cell", taggedWord.getWord());
    assertEquals("NN", taggedWord.getTag());
    taggedWord = taggedSentence.getTaggedWords().get(9);
